 files=[Path(__file__).resolve(),OLD/'initial_values.json',OLD/'media/physics_endpoint_contacts.json',P/'search_v2/search.json',P/'contact_region_v1.json']+sorted(P.glob('analysis_v*/*/verification.json'))+[p for folder in sorted(P.glob('native_v*/*/report.json'))for p in [folder.parent/'initial_values.json',folder.parent/'media/physics_endpoint_contacts.json']];inputs={str(p):sha(p)for p in files};old=read(OLD/'initial_values.json');old_ep=read(OLD/'media/physics_endpoint_contacts.json')['rows'];names=old['joint_names'];shoulder=[i for i,n in enumerate(names)if n.startswith('R_Shoulder_')];frozen=[i for i in range(81)if i not in shoulder];oldstates=dict(zip(old['human_body_names'],old['native_initial_state']['human_body_states']));front=pose(old['native_initial_state']['guitar_body_states'][0])[1].apply([0,0,1]);front[2]=0;front/=np.linalg.norm(front);region=read(P/'contact_region_v1.json')['cases'];cases={}
